function calculatorBench(a,b){
  const nodes=[],edges=[],wires=[];
  const add=(id,type,x,y,label,extra={})=>nodes.push(designNode(id,type,x,y,{label,...extra}));
  const out=(id,index=0)=>({node:id,side:'out',index});
  const input=(id,index=0)=>({node:id,side:'in',index});
  const connect=(from,to,style='normal',color='White')=>edges.push({from,to,style,color});
  for(let bit=0;bit<4;bit++){
    const y=96+bit*336,weight=2**bit;
    add('a'+bit,'lever',0,y,`A · ${weight}`,{on:!!(a&weight)});
    add('b'+bit,'lever',144,y,`B · ${weight}`,{on:!!(b&weight)});
    add('p'+bit,'xor',384,y,`A XOR B · ${weight}`);
    add('g'+bit,'and',384,y+144,'A AND B');
    add('s'+bit,'xor',672,y,`Sum · ${weight}`);
    add('h'+bit,'and',672,y+144,'Carry AND (A XOR B)');
    add('c'+bit,'or',960,y+144,bit===3?'Carry · +16':'Carry to next row');
    add('check'+bit,'xor',1536,y,`Mismatch · ${weight}`);
    for(const bank of ['a','b']){
      const index=bank==='a'?0:1;
      connect(out(bank+bit),input('p'+bit,index));connect(out(bank+bit),input('g'+bit,index));
      connect(out(bank+bit),input('reference',(bank==='a'?0:4)+3-bit));
    }
    connect(out('p'+bit),input('s'+bit));connect(out('p'+bit),input('h'+bit));
    if(bit){connect(out('c'+(bit-1)),input('s'+bit,1));connect(out('c'+(bit-1)),input('h'+bit,1));}
    connect(out('g'+bit),input('c'+bit));connect(out('h'+bit),input('c'+bit,1));
    connect(out('s'+bit),{x:1296,y:y+48},'neon','Cyan');
    connect(out('s'+bit),input('check'+bit));connect(out('reference',3-bit),input('check'+bit,1));
    connect(out('check'+bit),{x:1824,y:y+48},'neon','Red');
    connect(out('s'+bit),input('bcd',3-bit));
  }
  add('reference','fullAdder',288,1728,'Built-in reference · same A and B');
  add('check4','xor',1536,1440,'Mismatch · carry 16');
  connect(out('c3'),input('check4'));connect(out('reference',4),input('check4',1));
  connect(out('c3'),{x:1296,y:1488},'neon','Cyan');
  connect(out('check4'),{x:1824,y:1488},'neon','Red');
  add('bcd','binaryBCD',1008,1728,'Lower four bits → decimal');
  for(const [digit,x] of [['tens',1536],['units',1728]]){
    add(digit,'converter7',x,1872,'');
    add(digit+'Display','display7',x,1872,digit==='tens'?'Low bits · tens':'Low bits · units');
    for(let i=0;i<4;i++)connect(out('bcd',(digit==='tens'?0:4)+i),input(digit,i));
  }
  wires.push(...presetDesignWires(nodes,edges,'calc'));
  return {id:`calculator-${a}-${b}`,name:`Calculator bench · ${a} + ${b} = ${a+b}`,
    detail:'Eight labeled levers feed four gate-level full-adder rows and the built-in Full Adder. Rows run from weight 1 at the top to weight 8 at the bottom. Cyan wires show sum bits; red wires flag disagreements.',
    check:'All five red mismatch wires should stay dark. Read the cyan bits as 1, 2, 4, 8, then carry 16. The decimal displays show 0–15 from the lower four bits: add 16 when carry is lit. Every gate and wire is editable.',
    source:'https://www.socs.uoguelph.ca/~ggrewal/3120/L5.pdf',sourceLabel:'University of Guelph schematic',nodes,wires};
}
function routeSignature(nodes,edges){return JSON.stringify([nodes.map(n=>[n.id,n.type,n.x,n.y,n.rotation||0]),edges.map(e=>[e.from,e.to])]);}
function presetDesignWires(nodes,edges,prefix){
  const saved=PRESET_ROUTES[prefix];
  if(saved?.signature===routeSignature(nodes,edges))return edges.map((e,i)=>designWire(prefix+'-'+i,e.from,e.to,structuredClone(saved.points[i]),e.style,e.color));
  return routeDesignWires(nodes,edges,prefix);
}
