  const reserve=(path,wire)=>path.slice(1).forEach((b,i)=>{const a=path[i];if(near(a,b))return;const h=a.y===b.y,map=h?horizontal:vertical,key=h?a.y:a.x;if(!map.has(key))map.set(key,[]);map.get(key).push({wire,net:root(wire),lo:Math.min(h?a.x:a.y,h?b.x:b.y),hi:Math.max(h?a.x:a.y,h?b.x:b.y)});});
  const touches=(p,a,b)=>p.x>=Math.min(a.x,b.x)-1&&p.x<=Math.max(a.x,b.x)+1&&p.y>=Math.min(a.y,b.y)-1&&p.y<=Math.max(a.y,b.y)+1;
  const hits=(p,path)=>path.slice(1).some((b,i)=>touches(p,path[i],b));
  const boxes=nodes.map(n=>{const f=footprint(n);return {x:n.x,y:n.y,w:f.w,h:f.h};});
  const crossesBoard=(a,b)=>boxes.some(r=>a.x===b.x
    ?a.x>r.x&&a.x<r.x+r.w&&Math.max(a.y,b.y)>r.y&&Math.min(a.y,b.y)<r.y+r.h
    :a.y>r.y&&a.y<r.y+r.h&&Math.max(a.x,b.x)>r.x&&Math.min(a.x,b.x)<r.x+r.w);
